from pathlib import Path
import re,json
S=Path(__file__).resolve().parent
log=[]
def edit(rel,reps=(),transform=None):
 p=S/rel;t=p.read_text();o=t
 for a,b in reps:
  if a not in t:
   if b in t: continue
   raise ValueError((rel,a))
  t=t.replace(a,b)
 if transform:t=transform(t)
 if t!=o:
  b=S/'book_revision_before'/rel;b.parent.mkdir(parents=True,exist_ok=True)
  if not b.exists():b.write_bytes(p.read_bytes())
  p.write_text(t);log.append(rel)
edit('II/editable/traditional/Paper_II_Traditional_Final.tex',[(r'\textbf{Companions.} The worked visual atlas appears in this volume and as a separate guide. The Lean guide distinguishes the current formal development from the inherited 25-row walkthrough. Each guide records its evidence and scope.',r'\textbf{Companions.} The worked plates illustrate the constructions of this chapter. The formal companion in the back matter distinguishes the chapter-wide correspondence from the foundational 25-row walkthrough, with explicit evidence and scope.'),(r'\noindent This edition integrates the expanded mathematical narrative with the canonical v1.2.1 certificate level formulations.  It preserves the distinction between general written proofs, formal specifications, and finite computational examples.  The visual atlas and the separate Lean guide provide worked models and separate current and inherited formal crosswalks.',r'\noindent The exposition distinguishes general written proofs, formal specifications, and finite computational examples. The worked plates supply concrete models; the formal companion identifies the exact declarations and hypotheses that support each mapped statement.')])
edit('II/editable/visual_guide/Paper_II_Visual_Guide_Final.tex',[('current correspondence and the inherited theorem map. Each compiler claim belongs to its dated source-and-log record.','chapter-wide correspondence and the foundational theorem map. Each compiler claim belongs to the source and logs identified by its verification record.')])
edit('I/editable/machine/Paper_I_Machine_Native_Final.tex',[(r'\section*{Edition statement}\addcontentsline{toc}{section}{Edition statement}',r'\section*{Computational records and interfaces}\addcontentsline{toc}{section}{Computational records and interfaces}'),('This volume presents the machine representation of Chapter I as a mathematical object that can be inspected, queried, and executed. It accompanies the traditional paper and the Lean guide. The current manuscript record interface is \\nolinkurl{formal/coverage/COVERAGE_108.json}. The preserved executable runtime has its own versioned entrypoint under \\nolinkurl{source/machine_v1.0.1/}. This volume joins the current catalog to that explicitly scoped runtime specification.','This computational companion represents Chapter I as a collection of mathematical records that can be inspected and queried, with a finite subset supported by executable interfaces. The statement inventory is \\nolinkurl{formal/coverage/COVERAGE_108.json}. The executable runtime has its own entrypoint under \\nolinkurl{source/machine_v1.0.1/}; that path identifies the exact archived payload. The catalogue and runtime have the distinct scopes explained below.'),('This release synchronizes the catalog with the current traditional manuscript. Its 108 records include 69 theorem, proposition, corollary, and lemma records with source proofs. The current formal correspondence map is reported alongside each record.','The catalogue contains 108 mathematical records, including 69 theorem, proposition, corollary, and lemma records with source proofs. The formal correspondence is reported alongside each record.'),('The traditional edition supplies the current statements and proofs. The release catalog incorporates its clarified split-semisimple hypotheses, corrected notation, explicit map qualifications, and other final proofreading corrections. The supplementary worked models remain part of the traditional edition. Stable identifiers connect the three companions; current statement hashes and source locators distinguish this release from the preserved v1.0.0 and v1.0.1 machine payloads.','The mathematical source supplies the statements and proofs, including the split-semisimple hypotheses and explicit map qualifications. The supplementary worked models remain in the mathematical text. Stable identifiers connect the mathematical, formal, and computational material; statement hashes and source locators distinguish the catalogue from the archived runtime payloads.'),('The release verification record separates the current checks from preserved historical receipts.','The verification record distinguishes evidence for the mathematical correspondence from the runtime receipts.'),('Section 7 describes release reproduction.','Section 7 describes reproduction.'),('The current manuscript records are located at \\nolinkurl{formal/coverage/COVERAGE_108.json}; this release generates Appendix A directly from those records. Each includes the current statement, source proof where present, source location, hashes, formal status, and declaration correspondence. The current traditional source is the statement authority.','The mathematical records are located at \\nolinkurl{formal/coverage/COVERAGE_108.json}; Appendix A is generated directly from those records. Each includes the statement, source proof where present, source location, hashes, formal status, and declaration correspondence. The archived mathematical source identified by those hashes is the statement authority.'),('That digest identifies the preserved v1.0.1 runtime source. Its changes from v1.0.0 added explicit nonzero-packet assumptions to two corollaries and declared empty-family and poset-height conventions. The current manuscript contains later proofreading corrections and a clarified split-semisimple corollary; its statement and proof hashes are printed in Appendix A and preserved in the current inventory. Historical runtime receipts remain attached to their original bytes. The release change record documents the correspondence to the current manuscript.','That digest identifies the archived runtime source, including explicit nonzero-packet assumptions for two corollaries and the empty-family and poset-height conventions. The mathematical inventory has its own statement and proof hashes, printed in Appendix A. Runtime receipts remain attached to their original bytes; they do not transfer automatically to the mathematical inventory.'),('The current catalog uses the release formal correspondence map instead. Each of the 108 records carries a current status and scope note, and each proof-level statement has its own correspondence assessment. The release verification index distinguishes newly executed checks from inherited evidence.','The catalogue uses the formal correspondence map instead. Each of the 108 records carries a status and scope note, and each proof-level statement has its own correspondence assessment. The verification index distinguishes the execution evidence attached to each component.'),('The attached verification tranche records Lean 4.34.0-rc2 and a pinned Mathlib manifest. The map is dated 2 September 2026.','The attached seven-module formalization records Lean 4.34.0-rc2 and a pinned Mathlib manifest.'),('A separate historical report records 35 of 35 obligations for manuscript v1.2.0. The frozen status marks that lineage as noncanonical for the current expanded source. The historical count, the eight attached runtime mappings, and the current expanded correspondence map answer different questions.','A separate predecessor report records 35 of 35 obligations for its identified source. That lineage is not the canonical correspondence for the expanded mathematical inventory. The predecessor count, the eight attached runtime mappings, and the expanded correspondence map describe different scopes.'),(r'\subsection{Preserved reproduction for the earlier edition}',r'\subsection{Recorded runtime checks}'),('For the earlier edition, the documented release verifier and exact fixture suite were run from the corrected v1.0.1 payload. Both passed.','The documented verifier and exact fixture suite were run from the archived runtime payload. Both passed.'),('Typesetting this companion does not execute Lean. Current Lean checks are reported in the release evidence index and explained in the Lean guide.','Typesetting this companion does not execute Lean. Lean checks are reported in the verification index and explained in the formal companion.'),(r'\section{Reproduction and release maintenance}',r'\section{Reproducing the computational material}'),('From the machine companion directory, \\nolinkurl{build_companion.py} regenerates the current catalog from the release inventory and builds this PDF. The historical builder, retained as \\nolinkurl{build_historical_companion.py}, belongs to the preserved v1.0.1 workflow. Its runtime checks and examples are reproduced separately from the current manuscript inventory. A TeX installation with the packages declared in the preamble is required for either PDF build.','Within the original source archive, \\nolinkurl{build_companion.py} regenerates the catalogue from the mathematical inventory and builds the standalone PDF. The archived runtime builder, \\nolinkurl{build_historical_companion.py}, reproduces the runtime checks and examples separately from that inventory. These archive workflows are distinct from the collected monograph build. A TeX installation with the packages declared in the preamble is required for either PDF build.'),('The standalone source package includes a copy of the original machine release archive as provenance.','The original standalone source package includes the machine archive as provenance.'),('This release regenerates the current catalog from the final traditional source and records each statement and proof hash. The preserved v1.0.1 and v1.0.0 runtime payloads retain their versioned evidence.','The catalogue is generated from the archived mathematical source and records each statement and proof hash. The archived runtime payloads retain their own evidence.'),(r'\subsection{Archived interfaces and current prose}',r'\subsection{Runtime interfaces and mathematical statements}'),('The earlier machine-native PDFs are retained as provenance. This volume supplies the current statement catalog and the preserved runtime\'s exact transport-gate specification.','The source archive retains the earlier computational PDFs as provenance. This companion supplies the statement catalogue and the archived runtime\'s exact transport-gate specification.'),(r'\textbf{Proofreading scope.} The editorial prose, worked displays, generated links, tables, and record rendering were reviewed for local consistency. All 108 source statements and 69 proof bodies in the catalog are generated from the current traditional inventory. Typesetting changes remove outer statement environments and translate cross-references into stable-record links; they do not alter mathematical content. The release change record identifies differences from the preceding manuscript. Formal acceptance is reported separately in the current evidence index.',r'\textbf{Catalogue provenance.} The 108 source statements and 69 proof bodies are generated from the archived mathematical inventory. Their printed hashes identify that source wording. The catalogue removes outer statement environments and translates cross-references into stable-record links. Formal acceptance is documented separately in the verification index.')])
edit('I/editable/machine/generated/release_catalog.tex',[("This catalog is generated from the current traditional manuscript's 108 stable records. Every statement and attached proof comes from the release inventory. The current source locator and statement hash identify the exact wording.","This catalogue is generated from the archived mathematical inventory's 108 stable records. Every statement and attached proof comes from that inventory. The source locator and statement hash identify the exact archived wording."),('The formal-status line reports the current reviewed correspondence map','The formal-status line reports the reviewed correspondence map')])
# Eliminate obsolete local page citations only when the result/section is already named.
for rel in ['II/editable/traditional/visual_atlas.tex','II/editable/visual_guide/source/pages_final.tex']:
 edit(rel,transform=lambda t: re.sub(r'((?:Formalization target|Definition|Lemma|Theorem|Proposition|Corollary|Section)\s+(?:[A-Z]\.)?\d+(?:\.\d+)?)\s+\(p\.\s*[ivxlcdm0-9]+\)',r'\1',t))
# The formal crosswalk uses source statement numbers, avoiding obsolete component-page locators.
edit('II/editable/lean_guide/generated/current_traditional_crosswalk.tex',transform=lambda t: re.sub(r', p\.~[ivxlcdm0-9]+','',t).replace('Final locator','Chapter II locator'))
edit('II/editable/lean_guide/Paper_II_Lean_Guide_Final.tex',[("The printed page numbers below refer to the Chapter II mathematical text, whose cover is unnumbered and whose preliminary pages use Roman numerals. They are not PDF viewer page indices.","The locators below use statement and section numbers in the Chapter II mathematical text.")])
(S.parent/'editorial/book_revision/i_ii_second_edit_log.json').write_text(json.dumps(log,indent=2))
print(len(log),'files')
